from html import escape

VISION_TEXT = 'Turn back the hearts of the fathers to the children, and the disobedient and incredulous and unpersuadable to the wisdom of the upright [which is the knowledge and holy love of the will of God]—in order to make ready for the Lord a people [perfectly] prepared [in spirit, adjusted and disposed and placed in the right moral state].'
VISION_REFERENCE = 'Luke 1:17 · Amplified Bible, Classic Edition'
INSTAGRAM = 'https://www.instagram.com/apostles_church_of_christ/'

def vision_section():
    return f'''<section class="church-vision section" id="our-vision"><div class="wrap vision-layout"><div class="vision-heading" data-reveal><p class="eyebrow">OUR VISION</p><h2>A people<br>prepared<br>for the Lord.</h2><p class="vision-book">Luke 1:17</p></div><div class="vision-scripture" data-reveal><blockquote>{escape(VISION_TEXT)}</blockquote><p class="vision-reference">{VISION_REFERENCE}</p><p class="vision-cross-references">Isaiah 40:3 · Malachi 4:5–6</p><a class="text-link" href="https://www.biblegateway.com/passage/?search=Luke%201%3A17&amp;version=AMPC" target="_blank" rel="noopener noreferrer">Read the passage</a><p class="vision-credit">AMPC. Copyright © 1954, 1958, 1962, 1964, 1965, 1987 by The Lockman Foundation.</p></div></div></section>'''

def about_page(gallery):
    return f'''<section class="about-editorial wrap"><div class="about-editorial-copy"><p class="eyebrow" data-reveal>ABOUT OUR CHURCH</p><h1 data-reveal>A church<br>for the<br><span>nations.</span></h1><p class="about-editorial-lead" data-reveal>Apostles Church of Christ Dubai.</p><p data-reveal>We gather around the hope we find in Jesus, growing in His Word and sharing His love with one another.</p><div class="actions" data-reveal><a class="button" href="visit.html">Join a gathering</a><a class="text-link" href="#our-vision">Our vision</a></div></div><figure class="about-editorial-photo" data-reveal><img src="assets/pastor.webp" alt="Pastor Richard Mugisha" width="529" height="659" fetchpriority="high"><figcaption>Pastor Richard Mugisha</figcaption></figure></section>
    <section class="church-foundations section" id="our-foundations"><div class="wrap foundations-grid"><article data-reveal><h2>Our Values</h2><p>The Word, worship and prayer are at the heart of our community. We gather to grow in faith and encourage one another in Christ.</p><a class="foundation-link" href="#our-values">Explore our values</a></article><article data-reveal><h2>Our Vision</h2><p>To make ready for the Lord a people prepared in spirit, with hearts turned toward Him and one another.</p><a class="foundation-link" href="#our-vision">Read our vision</a></article><article data-reveal><h2>Our Mission</h2><p>To preach the Gospel of Jesus to the nations and to heal the broken-hearted.</p><a class="foundation-link" href="#our-mission">Our mission</a></article></div></section>
    {vision_section()}
    <section class="church-purpose section wrap"><div class="church-mission" id="our-mission" data-reveal><p class="eyebrow">OUR MISSION</p><h2>Sharing Jesus.<br>Bringing hope.</h2><p>Our mission is to preach the Gospel of Jesus to the nations and to heal the broken-hearted. Through biblical teaching, worship and prayer, we share messages that strengthen faith and inspire lives.</p><a class="text-link" href="{INSTAGRAM}" target="_blank" rel="noopener noreferrer">Connect with our church</a></div><div class="church-values" id="our-values" data-reveal><p class="eyebrow">OUR VALUES</p><article><h3>The Word</h3><p>Biblical teaching that points us to Christ and strengthens our faith.</p></article><article><h3>Worship</h3><p>Coming together to honour Jesus and share moments of worship.</p></article><article><h3>Prayer</h3><p>Turning to God and making space to pray with one another.</p></article></div></section>
    {gallery}
    <section class="about-invitation section"><div class="wrap"><p class="eyebrow" data-reveal>YOU ARE WELCOME HERE</p><h2 data-reveal>Come worship<br>with us.</h2><p data-reveal>Sunday and Thursday, 8–11 PM.<br>Saturday, 3–6 AM. Dubai time.</p><div class="actions" data-reveal><a class="button" href="visit.html">Plan your visit</a><a class="text-link" href="live.html">Join online</a></div></div></section>'''

def gallery_section(items):
    cards = ''.join(f'''<figure class="gallery-slide{' gallery-portrait' if v.get('height',800) > v.get('width',1200) else ''}"><img src="{escape(v['src'])}" alt="{escape(v['alt'])}" width="{v.get('width',1200)}" height="{v.get('height',800)}" loading="lazy" decoding="async" draggable="false"><figcaption>{escape(v.get('caption',''))}</figcaption></figure>''' for v in items)
    return f'''<section class="church-gallery section" id="church-gallery"><div class="wrap"><div class="section-heading"><div><p class="eyebrow" data-reveal>LIFE IN OUR CHURCH</p><h2 data-reveal>Our church<br>in pictures.</h2></div><a class="text-link" href="{INSTAGRAM}" target="_blank" rel="noopener noreferrer">Follow us on Instagram</a></div><div class="gallery-shell" data-gallery data-gallery-mode="continuous"><div class="gallery-viewport" id="gallery-viewport" tabindex="0" role="region" aria-label="Church photographs"><div class="gallery-track"><div class="gallery-sequence">{cards}</div></div></div><div class="gallery-toolbar"><p class="gallery-position">{len(items)} photographs <span>Drag or swipe to explore</span></p><div class="gallery-controls"><button type="button" data-gallery-pause aria-controls="gallery-viewport" hidden>Pause gallery</button></div></div></div></div></section>'''
